// Original game continuity inspired by Gordian, not a retelling of the TV ending.
export const CHAPTER_STORY={
 1:['EL LEGADO DESPIERTA','Victor Town resiste. Daigo comprende por qué su padre creó a Gordian: para proteger a quienes aún creen en el mañana. Desde Santore, Saori señala el camino hacia la cantera.'],
 2:['BAJO LA ROCA','Las máquinas de la cantera ocultan un paso hacia las defensas Madokter. Daigo libera a Protesser: allí donde la fuerza no alcanza, la agilidad puede abrir una brecha.'],
 3:['TRES CORAZAS, UNA VOLUNTAD','Clint encuentra la salida de los túneles. Al otro lado aguarda el bastión enemigo. Protesser entra en Dellinger, y ambos en Garbin: Daigo está listo para romper el cerco.'],
 4:['EL CAMINO A SANTORE','El centinela de acero ha caído. Pero sus fábricas siguen alimentando la invasión. Daigo avanza hacia la fundición para cortar los suministros antes de que otra legión alcance Santore.'],
 5:['LA CORRIENTE OSCURA','La fundición queda atrás. Saori detecta una corriente de energía que atraviesa la presa del crepúsculo. Si Gordian logra cruzarla, podrá alcanzar el reactor que sostiene la ofensiva.'],
 6:['EL PULSO DE LA FORTALEZA','Tras la presa, cada conducto conduce al mismo lugar. Dellinger se abre paso hacia el corazón del reactor. Daigo sabe que detener esa energía puede salvar miles de vidas.'],
 7:['EL REFLEJO DEL ENEMIGO','El reactor guarda una señal inquietante: una máquina con la silueta de Dellinger. Dokuma ha convertido un símbolo de esperanza en un arma de miedo. Garbin marchará a su encuentro.'],
 8:['UNA NUEVA OPORTUNIDAD','El guardián oscuro se derrumba. Desde Santore llegan reparaciones y cuatro vidas renovadas. Daigo vuelve a Protesser: más allá de la frontera comienza el último avance hacia Dokuma.'],
 9:['LA ÚLTIMA LEGIÓN','La frontera no está vacía. Entre las ruinas se reagrupan las máquinas supervivientes. Daigo y Clint siguen adelante: detrás de esa legión se encuentra el camino al mando enemigo.'],
 10:['ECOS DEL ECLIPSE','Los centinelas ya no bloquean el paso. Ahora aparecen copias del guardián oscuro, custodios del último acceso. Garbin deberá atravesarlas antes de que Dokuma reúna sus fuerzas.'],
 11:['POR LOS QUE ESPERAN','Saori envía un último mensaje: Santore sigue en pie. Daigo prepara a Garbin y mira hacia el trono de Dokuma. No lucha por conquistar este mundo, sino para que la humanidad pueda reconstruirlo.']};
export function victoryStory(levelId,robot){
 if(levelId===13)return {title:'EL CORAZÓN EN SILENCIO',body:'El Núcleo Madokter se apaga. Sus órdenes dejan de recorrer la fortaleza y las máquinas pierden su último vínculo. Daigo recibe la voz de Saori entre la estática: esta vez, el camino de regreso está abierto.'};
 if(levelId===14)return {title:'EL DESHIELO',body:'El rugido de Cryodrax se extingue. Bajo el hielo, la fortaleza queda inmóvil. Daigo y Clint vuelven la mirada hacia el horizonte: después de tanta oscuridad, aún queda un mundo por despertar.'};
 const next=robot==='dellinger'?'Sin embargo, bajo la fortaleza aún late el Núcleo Madokter. Gordian debe silenciarlo antes de regresar.':robot==='protesser'?'Una señal rompe el silencio desde el hielo: Cryodrax Prime ha despertado. La última defensa de Dokuma todavía amenaza a la humanidad.':'Por primera vez, las comunicaciones de Santore hablan de reconstrucción. Daigo sabe que esta victoria pertenece también a quienes resistieron.';
 return {title:'UN MAÑANA POSIBLE',body:'Grandmaster Dokuma ha caído. Su dominio se quiebra y Victor Town vuelve a mirar al futuro. El legado del padre de Daigo ha protegido aquello para lo que fue creado: la vida. '+next};
}
export function epilogueStory(extra){return {title:'GORDIAN SIEMPRE ESTARÁ LISTO',body:'En Santore comienza un nuevo día. Saori reúne a los supervivientes y Clint acompaña a Daigo de regreso. Protesser, Dellinger y Garbin descansan, unidos por una misma promesa: proteger a la humanidad.',note:extra?'Los enemigos nunca conceden un descanso definitivo. Pero mientras exista una amenaza, Gordian estará listo para volver a luchar.':'El futuro sigue abierto. Mientras haya personas que proteger, el legado de Gordian seguirá vivo.'};}
